        r = Step(machine, dispenser, r.Account, D(0, 0, 1), Ok(NoteCounts.None, 0, 110, 20), N(0, 5, 1));
        Step(machine, dispenser, r.Account, W(10), Ok(N(0, 0, 1), 0, 100, 30), N(0, 5, 0));
