import sys, itertools, pickle
from collections import Counter, defaultdict
from model import fewest, avail
W,D=pickle.load(open('/tmp/w/cov.pkl','rb'))
def fee(a): return 5 if a>100 else 0
AM=[a for a in range(10,201,10)]
def pf(f,t,c,j,a):
    av=avail(f,t,c,j); comb=fewest(a,*av)
    if comb is None: return dict(disp=0,tot=-1,passes=-1,u10=-1,jam=j,emp=-1)
    tot=sum(comb)
    return dict(disp=1,tot=tot,passes=(tot+3)//4,u10=int(comb[2]>0),jam=j,emp=int(any(comb[i]==av[i] and av[i]>0 for i in range(3))))
def af(b,w,a):
    return dict(db=b-a-fee(a), dw=200-w-a, fee=fee(a))
PK=list(pf(5,5,5,0,50).keys()); AK=list(af(100,0,50).keys())
cov=Counter()
for (b,w,f,t,c,j,a) in W:
    if a<=0 or a%10 or a>200: continue
    p=pf(f,t,c,j,a); q=af(b,w,a)
    for pk in PK:
        for ak in AK:
            for ak2 in AK:
                if ak2<=ak: continue
                cov[(pk,ak,ak2,p[pk],q[ak],q[ak2])]+=1
dom=Counter()
for a in AM:
    cp=defaultdict(Counter)
    for f,t,c in itertools.product(range(6),repeat=3):
        for j in (0,50,20,10):
            p=pf(f,t,c,j,a)
            for pk in PK: cp[pk][p[pk]]+=1
    ca=Counter()
    for b in range(0,251,5):
        for w in range(0,201,10):
            q=af(b,w,a); ca[tuple(q[k] for k in AK)]+=1
    for pk in PK:
        for i,ak in enumerate(AK):
            for i2,ak2 in enumerate(AK):
                if ak2<=ak: continue
                cc=Counter()
                for k,n in ca.items(): cc[(k[i],k[i2])]+=n
                for pv,n in cp[pk].items():
                    for (v1,v2),m in cc.items(): dom[(pk,ak,ak2,pv,v1,v2)]+=n*m
unc=[(n,k) for k,n in dom.items() if cov[k]==0]
# keep only "near threshold" cells
unc=[(n,k) for n,k in unc if (k[1]!='db' or abs(k[4])<=20) ]
unc.sort(reverse=True)
for u in unc[:60]: print(u)
